INSERT OR IGNORE INTO tasks(id,title,kind,state,why,if_wait,url,identity,source,priority,updated_at) VALUES('own-file','File the provisional patent','owner','open','Draft v3 is ready for attorney review. Ask the patent attorney what, if anything, in the public QNFO repos overlaps the claims, and what filing timeline follows.','The site, grant applications and pitch stay gated until the filing decision is made.','https://github.com/ultrastable/ultrastable/issues/30',1,'seed',1,1794301562467);
INSERT OR IGNORE INTO tasks(id,title,kind,state,why,if_wait,url,identity,source,priority,updated_at) VALUES('own-google','Submit the Google for Startups Cloud Program application','owner','open','Needs the site and domain email live; the drafts are in the funding docs.','Credits are needed to keep developing without paying out of pocket.','https://github.com/ultrastable/ultrastable/issues/17',1,'seed',1,1794301562467);
INSERT OR IGNORE INTO tasks(id,title,kind,state,why,if_wait,url,identity,source,priority,updated_at) VALUES('own-gate','Decide: holding page or public site until filing (#52)','owner','open','Default in effect: the site serves a generic holding page. Tap Done to confirm, or Not doing to restore the old site.','The old public text describes mechanisms at a high level.','https://github.com/ultrastable/ultrastable/issues/52',0,'seed',1,1794301562467);
INSERT OR IGNORE INTO tasks(id,title,kind,state,why,if_wait,url,identity,source,priority,updated_at) VALUES('own-gh-token','Give the dashboard a GitHub token so it can sync issues and label fleet work','owner','open','A fine-grained token with Issues read/write on the ultrastable repo, stored as the GITHUB_TOKEN secret. Only you can mint it.','Until then the task list is a seeded copy and Hand to fleet only queues locally.',NULL,1,'seed',2,1794301562467);
